import{_ as t,o as s,c as n,ag as r}from"./chunks/framework.BRELbxIe.js";const m=JSON.parse(`{"title":"La carte : qui est qui","description":"","frontmatter":{},"headers":[],"relativePath":"handout-01-carte.md","filePath":"handout-01-carte.md","handout":{"fichier":"handout-01-carte.md","markdown":"# Handout — La carte : qui est qui\\n\\n**L'IA sous le capot — version métiers · Zenika · fiche partie 1**\\n\\nSix mots qu'on entend partout en réunion, une image pour chacun : une entreprise de livraison, ses moteurs, ses véhicules, son dispatch. Cette fiche pose le décor de toute la session et le vocabulaire commun.\\n\\n> **Le fil rouge** : suivre une demande, de la question posée à l'assistant jusqu'au travail livré. Chaque partie ajoute une pièce au décor routier : le moteur (partie 2), le véhicule (3), la flotte (4), le code de la route (5).\\n\\n## Le trajet d'une demande\\n\\n_Ouverture · slide « À la fin de la session, vous saurez… »_\\n\\nUne demande part de votre ordinateur, monte dans un **véhicule** (l'assistant), passe par le **boîtier de la flotte** (le contrôle de l'entreprise), atteint le **moteur** (le modèle), prend des **outils** et arrive validée. À la fin de la session, vous saurez expliquer à un collègue ce qui se passe quand on pose une question à un assistant IA, et quelles questions poser avant d'adopter un outil.\\n\\n| Partie | Vous saurez                       | Image                       |\\n| ------ | --------------------------------- | --------------------------- |\\n| 1      | **Situer** : qui est qui          | la carte                    |\\n| 2      | **Comprendre** le modèle          | le moteur                   |\\n| 3      | **Reconnaître** un agent          | le véhicule                 |\\n| 4      | **Organiser** une flotte d'agents | l'équipement, le dispatch   |\\n| 5      | **Questionner** sécurité et coûts | le boîtier et ses contrôles |\\n\\nLe mot technique n'est donné qu'une fois, sous l'image, pour que vous le reconnaissiez ensuite en réunion.\\n\\n## Une entreprise de livraison\\n\\n_Partie 1 · slide « Une entreprise de livraison »_\\n\\n> **Le moteur ne livre rien tout seul.** Pour livrer, il faut un véhicule, un chauffeur, de l'équipement, un dispatch et des bons de commande.\\n\\n| Mot technique     | L'image                              | En clair                                                                                                                                            |\\n| ----------------- | ------------------------------------ | --------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **LLM**           | le **moteur**                        | le grand modèle de langage : puissant, mais il ne fait que tourner (ChatGPT, Claude, Gemini, Mistral sont bâtis autour d'un moteur de ce type)      |\\n| **SLM**           | le petit moteur, la **citadine**     | un petit modèle : moins puissant, moins cher, il peut rester « au garage », c'est-à-dire tourner sur vos machines sans envoyer vos données ailleurs |\\n| **Agent**         | le **véhicule** en mission           | un moteur, un chauffeur, des outils et une destination : il décide lui-même de sa route                                                             |\\n| **Harness**       | l'**équipement** du véhicule         | grand coffre pour les meubles, caisson frigo pour le frais : même moteur, véhicules très différents                                                 |\\n| **Orchestrateur** | le **dispatch**                      | il répartit les tournées entre plusieurs véhicules                                                                                                  |\\n| **SDD**           | le **dispatch par bons de commande** | rien ne part sans bon signé, et chaque bon devient une tournée confiée à un agent                                                                   |\\n\\nCe qui distingue deux produits construits sur le même modèle, c'est l'équipement, pas le moteur. Le boîtier de la flotte (gateway) et ses contrôles (guardrails) complètent le décor en partie 5.\\n\\n> **Limite de l'image** : un vrai moteur ne décide rien ; un modèle d'IA, lui, choisit la prochaine action d'un agent.\\n\\n## Pas à pas, bus ou taxi ?\\n\\n_Partie 1 · complément de la slide « Une entreprise de livraison »_\\n\\n> **Plus l'IA décide du trajet, plus c'est souple, et moins c'est prévisible.**\\n\\n| Image                   | Mot technique | Qui décide ?     | Exemple                                                                                                                                   |\\n| ----------------------- | ------------- | ---------------- | ----------------------------------------------------------------------------------------------------------------------------------------- |\\n| La **course pas à pas** | chatbot       | **vous**         | ChatGPT, Le Chat, Copilot dans Teams en simple conversation : vous passez chaque commande, il fait la course, vous décidez de la suivante |\\n| La **ligne de bus**     | workflow      | **le programme** | un mail arrive, l'IA le classe, l'IA le résume, on l'envoie au bon service                                                                |\\n| Le **taxi**             | agent         | **l'IA**         | « prépare la synthèse des retours clients du mois » : il choisit ses fichiers, ses outils, son arrêt                                      |\\n\\n- Le **bus** est prévisible, peu cher, facile à vérifier.\\n- Le **taxi** est souple, mais on ne sait pas à l'avance combien de détours il fera, ni combien ça coûtera.\\n- Le conseil des spécialistes (Anthropic, _Building effective agents_, 2024) : prendre la solution la plus simple qui marche. Si le trajet est connu, un bus suffit.\\n\\nPour vous : dans votre métier, quelle tâche relève du bus, laquelle du taxi ?\\n\\n## Qui parle à qui\\n\\n_Partie 1 · slide « Qui parle à qui »_\\n\\n> **Le moteur propose, le véhicule agit.**\\n\\n1. **Vous** formulez une demande dans un outil (un assistant, un agent).\\n2. **Le véhicule** (le logiciel autour du modèle) prépare le message : votre demande, les documents utiles, les consignes.\\n3. **Le boîtier de la flotte** (la gateway), dans une entreprise outillée, posé entre le véhicule et le moteur : il vérifie, il compte, il masque les données sensibles.\\n4. **Le moteur** (le modèle) répond. Souvent, par une demande d'action : « ouvre tel fichier », « envoie tel mail ».\\n5. **Le véhicule** décide d'exécuter ou non cette action, puis renvoie le résultat au moteur. Et ainsi de suite.\\n\\nLe modèle ne fait qu'écrire : il ne clique sur rien, il n'envoie rien. C'est le logiciel autour qui agit, et c'est donc là qu'on place les autorisations et les garde-fous (partie 5).\\n\\nPour un usage individuel (ChatGPT sur son téléphone), il n'y a souvent pas de boîtier d'entreprise : vos données vont directement chez le fournisseur.\\n\\n## Quiz : qui est qui ?\\n\\n_Partie 1 · slide « Quiz : qui est qui ? »_\\n\\nOn classe des **rôles**, pas des marques : un même produit peut jouer plusieurs rôles.\\n\\n| Produit                      | Rôle                             | Image                                  | Pourquoi                                                                                                                   |\\n| ---------------------------- | -------------------------------- | -------------------------------------- | -------------------------------------------------------------------------------------------------------------------------- |\\n| ChatGPT                      | **assistant : harness + outils** | le véhicule à qui vous passez commande | plus qu'un chatbot : recherche web, fichiers, mémoire, mode agent autour d'un moteur ; vous êtes le commanditaire          |\\n| GPT-5, Claude, Mistral Large | **LLM**                          | le moteur                              | les modèles eux-mêmes ; un même moteur équipe plusieurs produits                                                           |\\n| Mistral Small sur Ollama     | **SLM en local**                 | la citadine                            | un petit modèle qui tourne sur un poste ; Ollama est le logiciel qui le fait tourner                                       |\\n| Copilot agent                | **agent**                        | le véhicule                            | il agit dans vos outils Microsoft 365                                                                                      |\\n| Power Automate + IA          | **workflow**                     | la ligne de bus                        | les étapes sont fixées par la personne qui a conçu le flux                                                                 |\\n| NotebookLM                   | **assistant sur vos sources**    | il travaille à livre ouvert            | un produit, pas une technique : il répond à partir des sources que vous lui donnez ; le RAG est une des façons de le faire |\\n| MCP                          | **protocole d'outils**           | le quai de chargement standard         | ni un agent ni un outil : la norme commune des quais, chaque service ouvre le sien                                         |\\n| Claude Code                  | **harness + agent**              | l'équipement                           | l'équipement autour du modèle Claude, surtout pour les développeurs                                                        |\\n| LangGraph                    | **orchestrateur**                | le dispatch                            | il fait travailler plusieurs agents                                                                                        |\\n| GitHub Spec Kit              | **SDD**                          | le dispatch par bons de commande       | il fait écrire la spécification, la découpe en tâches et pilote les agents tâche par tâche                                 |\\n| Llama Guard                  | **guardrail**                    | un contrôle du boîtier                 | un petit modèle qui filtre ce qui entre dans le moteur et ce qui en sort                                                   |\\n| LiteLLM                      | **gateway**                      | le boîtier                             | le point de passage unique vers les modèles                                                                                |\\n"}}`),i={name:"handout-01-carte.md"};function o(a,e,u,l,d,c){return s(),n("div",null,[...e[0]||(e[0]=[r('<p class="zh-type">fiche partie 1</p><h1 id="handout-la-carte-qui-est-qui" tabindex="-1">La carte : qui est qui <a class="header-anchor" href="#handout-la-carte-qui-est-qui" aria-label="Permalink to &quot;Handout — La carte : qui est qui&quot;">​</a></h1><p>Six mots qu’on entend partout en réunion, une image pour chacun : une entreprise de livraison, ses moteurs, ses véhicules, son dispatch. Cette fiche pose le décor de toute la session et le vocabulaire commun.</p><blockquote><p><strong>Le fil rouge</strong> : suivre une demande, de la question posée à l’assistant jusqu’au travail livré. Chaque partie ajoute une pièce au décor routier : le moteur (partie 2), le véhicule (3), la flotte (4), le code de la route (5).</p></blockquote><h2 id="le-trajet-d-une-demande" tabindex="-1">Le trajet d’une demande <a class="header-anchor" href="#le-trajet-d-une-demande" aria-label="Permalink to &quot;Le trajet d&#39;une demande&quot;">​</a></h2><p><em>Ouverture · slide « À la fin de la session, vous saurez… »</em></p><p>Une demande part de votre ordinateur, monte dans un <strong>véhicule</strong> (l’assistant), passe par le <strong>boîtier de la flotte</strong> (le contrôle de l’entreprise), atteint le <strong>moteur</strong> (le modèle), prend des <strong>outils</strong> et arrive validée. À la fin de la session, vous saurez expliquer à un collègue ce qui se passe quand on pose une question à un assistant IA, et quelles questions poser avant d’adopter un outil.</p><table tabindex="0"><thead><tr><th>Partie</th><th>Vous saurez</th><th>Image</th></tr></thead><tbody><tr><td>1</td><td><strong>Situer</strong> : qui est qui</td><td>la carte</td></tr><tr><td>2</td><td><strong>Comprendre</strong> le modèle</td><td>le moteur</td></tr><tr><td>3</td><td><strong>Reconnaître</strong> un agent</td><td>le véhicule</td></tr><tr><td>4</td><td><strong>Organiser</strong> une flotte d’agents</td><td>l’équipement, le dispatch</td></tr><tr><td>5</td><td><strong>Questionner</strong> sécurité et coûts</td><td>le boîtier et ses contrôles</td></tr></tbody></table><p>Le mot technique n’est donné qu’une fois, sous l’image, pour que vous le reconnaissiez ensuite en réunion.</p><h2 id="une-entreprise-de-livraison" tabindex="-1">Une entreprise de livraison <a class="header-anchor" href="#une-entreprise-de-livraison" aria-label="Permalink to &quot;Une entreprise de livraison&quot;">​</a></h2><p><em>Partie 1 · slide « Une entreprise de livraison »</em></p><blockquote><p><strong>Le moteur ne livre rien tout seul.</strong> Pour livrer, il faut un véhicule, un chauffeur, de l’équipement, un dispatch et des bons de commande.</p></blockquote><table tabindex="0"><thead><tr><th>Mot technique</th><th>L’image</th><th>En clair</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>le <strong>moteur</strong></td><td>le grand modèle de langage : puissant, mais il ne fait que tourner (ChatGPT, Claude, Gemini, Mistral sont bâtis autour d’un moteur de ce type)</td></tr><tr><td><strong>SLM</strong></td><td>le petit moteur, la <strong>citadine</strong></td><td>un petit modèle : moins puissant, moins cher, il peut rester « au garage », c’est-à-dire tourner sur vos machines sans envoyer vos données ailleurs</td></tr><tr><td><strong>Agent</strong></td><td>le <strong>véhicule</strong> en mission</td><td>un moteur, un chauffeur, des outils et une destination : il décide lui-même de sa route</td></tr><tr><td><strong>Harness</strong></td><td>l’<strong>équipement</strong> du véhicule</td><td>grand coffre pour les meubles, caisson frigo pour le frais : même moteur, véhicules très différents</td></tr><tr><td><strong>Orchestrateur</strong></td><td>le <strong>dispatch</strong></td><td>il répartit les tournées entre plusieurs véhicules</td></tr><tr><td><strong>SDD</strong></td><td>le <strong>dispatch par bons de commande</strong></td><td>rien ne part sans bon signé, et chaque bon devient une tournée confiée à un agent</td></tr></tbody></table><p>Ce qui distingue deux produits construits sur le même modèle, c’est l’équipement, pas le moteur. Le boîtier de la flotte (gateway) et ses contrôles (guardrails) complètent le décor en partie 5.</p><blockquote><p><strong>Limite de l’image</strong> : un vrai moteur ne décide rien ; un modèle d’IA, lui, choisit la prochaine action d’un agent.</p></blockquote><h2 id="pas-a-pas-bus-ou-taxi" tabindex="-1">Pas à pas, bus ou taxi ? <a class="header-anchor" href="#pas-a-pas-bus-ou-taxi" aria-label="Permalink to &quot;Pas à pas, bus ou taxi ?&quot;">​</a></h2><p><em>Partie 1 · complément de la slide « Une entreprise de livraison »</em></p><blockquote><p><strong>Plus l’IA décide du trajet, plus c’est souple, et moins c’est prévisible.</strong></p></blockquote><table tabindex="0"><thead><tr><th>Image</th><th>Mot technique</th><th>Qui décide ?</th><th>Exemple</th></tr></thead><tbody><tr><td>La <strong>course pas à pas</strong></td><td>chatbot</td><td><strong>vous</strong></td><td>ChatGPT, Le Chat, Copilot dans Teams en simple conversation : vous passez chaque commande, il fait la course, vous décidez de la suivante</td></tr><tr><td>La <strong>ligne de bus</strong></td><td>workflow</td><td><strong>le programme</strong></td><td>un mail arrive, l’IA le classe, l’IA le résume, on l’envoie au bon service</td></tr><tr><td>Le <strong>taxi</strong></td><td>agent</td><td><strong>l’IA</strong></td><td>« prépare la synthèse des retours clients du mois » : il choisit ses fichiers, ses outils, son arrêt</td></tr></tbody></table><ul><li>Le <strong>bus</strong> est prévisible, peu cher, facile à vérifier.</li><li>Le <strong>taxi</strong> est souple, mais on ne sait pas à l’avance combien de détours il fera, ni combien ça coûtera.</li><li>Le conseil des spécialistes (Anthropic, <em>Building effective agents</em>, 2024) : prendre la solution la plus simple qui marche. Si le trajet est connu, un bus suffit.</li></ul><p>Pour vous : dans votre métier, quelle tâche relève du bus, laquelle du taxi ?</p><h2 id="qui-parle-a-qui" tabindex="-1">Qui parle à qui <a class="header-anchor" href="#qui-parle-a-qui" aria-label="Permalink to &quot;Qui parle à qui&quot;">​</a></h2><p><em>Partie 1 · slide « Qui parle à qui »</em></p><blockquote><p><strong>Le moteur propose, le véhicule agit.</strong></p></blockquote><ol><li><strong>Vous</strong> formulez une demande dans un outil (un assistant, un agent).</li><li><strong>Le véhicule</strong> (le logiciel autour du modèle) prépare le message : votre demande, les documents utiles, les consignes.</li><li><strong>Le boîtier de la flotte</strong> (la gateway), dans une entreprise outillée, posé entre le véhicule et le moteur : il vérifie, il compte, il masque les données sensibles.</li><li><strong>Le moteur</strong> (le modèle) répond. Souvent, par une demande d’action : « ouvre tel fichier », « envoie tel mail ».</li><li><strong>Le véhicule</strong> décide d’exécuter ou non cette action, puis renvoie le résultat au moteur. Et ainsi de suite.</li></ol><p>Le modèle ne fait qu’écrire : il ne clique sur rien, il n’envoie rien. C’est le logiciel autour qui agit, et c’est donc là qu’on place les autorisations et les garde-fous (partie 5).</p><p>Pour un usage individuel (ChatGPT sur son téléphone), il n’y a souvent pas de boîtier d’entreprise : vos données vont directement chez le fournisseur.</p><h2 id="quiz-qui-est-qui" tabindex="-1">Quiz : qui est qui ? <a class="header-anchor" href="#quiz-qui-est-qui" aria-label="Permalink to &quot;Quiz : qui est qui ?&quot;">​</a></h2><p><em>Partie 1 · slide « Quiz : qui est qui ? »</em></p><p>On classe des <strong>rôles</strong>, pas des marques : un même produit peut jouer plusieurs rôles.</p><table tabindex="0"><thead><tr><th>Produit</th><th>Rôle</th><th>Image</th><th>Pourquoi</th></tr></thead><tbody><tr><td>ChatGPT</td><td><strong>assistant : harness + outils</strong></td><td>le véhicule à qui vous passez commande</td><td>plus qu’un chatbot : recherche web, fichiers, mémoire, mode agent autour d’un moteur ; vous êtes le commanditaire</td></tr><tr><td>GPT-5, Claude, Mistral Large</td><td><strong>LLM</strong></td><td>le moteur</td><td>les modèles eux-mêmes ; un même moteur équipe plusieurs produits</td></tr><tr><td>Mistral Small sur Ollama</td><td><strong>SLM en local</strong></td><td>la citadine</td><td>un petit modèle qui tourne sur un poste ; Ollama est le logiciel qui le fait tourner</td></tr><tr><td>Copilot agent</td><td><strong>agent</strong></td><td>le véhicule</td><td>il agit dans vos outils Microsoft 365</td></tr><tr><td>Power Automate + IA</td><td><strong>workflow</strong></td><td>la ligne de bus</td><td>les étapes sont fixées par la personne qui a conçu le flux</td></tr><tr><td>NotebookLM</td><td><strong>assistant sur vos sources</strong></td><td>il travaille à livre ouvert</td><td>un produit, pas une technique : il répond à partir des sources que vous lui donnez ; le RAG est une des façons de le faire</td></tr><tr><td>MCP</td><td><strong>protocole d’outils</strong></td><td>le quai de chargement standard</td><td>ni un agent ni un outil : la norme commune des quais, chaque service ouvre le sien</td></tr><tr><td>Claude Code</td><td><strong>harness + agent</strong></td><td>l’équipement</td><td>l’équipement autour du modèle Claude, surtout pour les développeurs</td></tr><tr><td>LangGraph</td><td><strong>orchestrateur</strong></td><td>le dispatch</td><td>il fait travailler plusieurs agents</td></tr><tr><td>GitHub Spec Kit</td><td><strong>SDD</strong></td><td>le dispatch par bons de commande</td><td>il fait écrire la spécification, la découpe en tâches et pilote les agents tâche par tâche</td></tr><tr><td>Llama Guard</td><td><strong>guardrail</strong></td><td>un contrôle du boîtier</td><td>un petit modèle qui filtre ce qui entre dans le moteur et ce qui en sort</td></tr><tr><td>LiteLLM</td><td><strong>gateway</strong></td><td>le boîtier</td><td>le point de passage unique vers les modèles</td></tr></tbody></table>',31)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
